@Transactional
public AssignOutcome assign(String requestId, long segmentId, long pilotId) {
    Optional<Assignment> existing = assignmentRepo.findByRequestId(requestId);
    if (existing.isPresent()) {
        Assignment a = existing.get();
        if (a.segmentId() == segmentId && a.pilotId() == pilotId) return new AssignOutcome(a, true);
        throw ApiException.conflict("IDEMPOTENCY_CONFLICT", ...);
    }
    Pilot pilot = pilotRepo.findByIdForUpdate(pilotId).orElseThrow(notFound);
    Segment segment = segmentRepo.findById(segmentId).orElseThrow(notFound);
    if (segment.status() != REQUESTED) throw conflict("SEGMENT_NOT_ASSIGNABLE");
    if (!pilot.active()) throw unprocessable("PILOT_INACTIVE");
    if (pilot.qualificationGrade() < segment.requiredGrade()) throw unprocessable("QUALIFICATION_INSUFFICIENT");
    if (!assignmentRepo.findOccupiedOverlapping(pilotId, segment.estStartUtc(), segment.estEndUtc()).isEmpty())
        throw conflict("PILOT_INTERVAL_OVERLAP");
    try {
        long id = assignmentRepo.insert(...);
    } catch (DuplicateKeyException e) {
        // concurrent same requestId: re-read and compare
        ... but we're in a transaction that may be marked rollback-only. DuplicateKeyException from H2 constraint violation — in H2, the transaction may still be usable? With H2, a constraint violation doesn't abort the whole transaction (unlike Postgres). Spring's DataAccessException — transaction not marked rollback-only automatically unless configured. So catch, re-query findByRequestId, compare, return replay or throw conflict. OK.
    }
    segmentRepo.updateStatus(segmentId, ASSIGNED, null);
    return new AssignOutcome(findById(id), false);
}
